   [13]={next_id=14, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你当然了解那段历史——那时候的维雷德克家族几乎如日中天，掌控了国内大量的财富，被克罗瓦德上下无数双眼睛盯着。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_202.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
